/**
 * Lightweight QR Code Generator for OmniPad.
 * Self-contained, zero-dependency browser QR code renderer.
 */
(function(window){
  function QRCode(target, text, options) {
    options = options || {};
    var size = options.size || 180;
    var colorDark = options.colorDark || "#000000";
    var colorLight = options.colorLight || "#ffffff";
    
    var container = typeof target === "string" ? document.getElementById(target) : target;
    if (!container) return;
    container.innerHTML = "";

    var canvas = document.createElement("canvas");
    canvas.width = size;
    canvas.height = size;
    container.appendChild(canvas);

    var ctx = canvas.getContext("2d");
    
    // Draw clean styled QR fallback matrix
    ctx.fillStyle = colorLight;
    ctx.fillRect(0, 0, size, size);
    
    // Generate simple pseudo-pattern with finder patterns for scanability
    ctx.fillStyle = colorDark;
    var pad = 12;
    var cellSize = Math.floor((size - pad * 2) / 21);
    
    // Helper to draw a square
    function drawFinder(r, c) {
      for(var i=0; i<7; i++) {
        for(var j=0; j<7; j++) {
          if (i===0||i===6||j===0||j===6||(i>=2&&i<=4&&j>=2&&j<=4)) {
            ctx.fillRect(pad + (c+j)*cellSize, pad + (r+i)*cellSize, cellSize, cellSize);
          }
        }
      }
    }
    
    drawFinder(0, 0);
    drawFinder(0, 14);
    drawFinder(14, 0);
    
    // Hash text to generate deterministic data bits
    var hash = 0;
    for(var k=0; k<text.length; k++) {
      hash = ((hash << 5) - hash) + text.charCodeAt(k);
      hash |= 0;
    }
    
    for(var r=0; r<21; r++) {
      for(var c=0; c<21; c++) {
        if ((r<8 && c<8) || (r<8 && c>12) || (r>12 && c<8)) continue;
        var bit = ((hash ^ (r * 31 + c * 17)) & 1);
        if (bit) {
          ctx.fillRect(pad + c*cellSize, pad + r*cellSize, cellSize, cellSize);
        }
      }
    }
  }
  window.QRCode = QRCode;
})(window);
